from agents import Agent, Runner, function_tool, MaxTurnsExceeded

@function_tool
def get_swap_request(msisdn: str) -> str:
    """Latest SIM swap request for a mobile number: id, status, time."""
    return "req 55120 · status: provisioning_failed · 10:42"

@function_tool
def get_provisioning_log(request_id: str) -> str:
    """Short error summary for a provisioning job."""
    return "HLR update rejected: IMSI already active"

@function_tool
def raise_ticket(summary: str, team: str) -> str:
    """Open a ticket for the named back-office team."""
    return "ticket NOC-8812 created"

agent = Agent(
    name="SIM swap support",
    instructions="Diagnose failed SIM swaps. Use tools; keep answers short. "
                 "If a tool returns an error, read it and try another route.",
    tools=[get_swap_request, get_provisioning_log, raise_ticket],
)

try:
    result = Runner.run_sync(agent, "My SIM swap for 98xxxxxx21 failed. Why?",
                             max_turns=8)              # hard step cap
    print(result.final_output)
except MaxTurnsExceeded:
    print("Stopped at 8 turns; escalating to a human.")
